	@Test
	public void testEmptyNamespace() {
		IRI uri1 = vf.createIRI(exNs, "uri1");
		IRI uri2 = vf.createIRI(exNs, "uri2");

		StringWriter w = new StringWriter();

		RDFWriter rdfWriter = rdfWriterFactory.getWriter(w);
		rdfWriter.getWriterConfig().set(JSONLDSettings.JSONLD_MODE, JSONLDMode.COMPACT);
		rdfWriter.startRDF();
		rdfWriter.handleNamespace("", exNs);
		rdfWriter.handleNamespace(DCTERMS.PREFIX, DCTERMS.NAMESPACE);
		rdfWriter.handleStatement(vf.createStatement(uri1, DCTERMS.TITLE, vf.createBNode()));
		rdfWriter.handleStatement(vf.createStatement(uri1, uri2, vf.createBNode()));
		rdfWriter.endRDF();

		assertTrue(w.toString().contains("@vocab"), "Does not contain @vocab");
	}

	@Test
	public void testRoundTripNamespaces() throws Exception {
		IRI uri1 = vf.createIRI(exNs, "uri1");
		IRI uri2 = vf.createIRI(exNs, "uri2");
		Literal plainLit = vf.createLiteral("plain", XSD.STRING);

		Statement st1 = vf.createStatement(uri1, uri2, plainLit);

		ByteArrayOutputStream out = new ByteArrayOutputStream();
		RDFWriter rdfWriter = rdfWriterFactory.getWriter(out);
		rdfWriter.getWriterConfig().set(JSONLDSettings.JSONLD_MODE, JSONLDMode.COMPACT);
		rdfWriter.startRDF();
		rdfWriter.handleNamespace("ex", exNs);
		rdfWriter.handleStatement(st1);
		rdfWriter.endRDF();

		ByteArrayInputStream in = new ByteArrayInputStream(out.toByteArray());
		RDFParser rdfParser = rdfParserFactory.getParser();
		ParserConfig config = new ParserConfig();
		config.set(BasicParserSettings.FAIL_ON_UNKNOWN_DATATYPES, true);
		config.set(BasicParserSettings.FAIL_ON_UNKNOWN_LANGUAGES, true);
		rdfParser.setParserConfig(config);
		rdfParser.setValueFactory(vf);
		Model model = new LinkedHashModel();
		rdfParser.setRDFHandler(new StatementCollector(model));

		rdfParser.parse(in, "foo:bar");

		assertEquals(1, model.size(), "Unexpected number of statements, found " + model.size());

		assertTrue(model.contains(st1), "missing namespaced statement");

		if (rdfParser.getRDFFormat().supportsNamespaces()) {
			assertTrue(!model.getNamespaces().isEmpty(),
					"Expected at least one namespace, found " + model.getNamespaces().size());
			assertEquals(exNs, model.getNamespace("ex").get().getName());
		}
	}

	/**
	 * Test if the JSON-LD writer honors the "native RDF type" setting.
	 */
	@Test
	public void testNativeRDFTypes() {
		IRI subject = vf.createIRI(exNs, "uri1");
		IRI predicate = vf.createIRI(exNs, "uri2");
		Literal object = vf.createLiteral(true);
		Statement stmt = vf.createStatement(subject, predicate, object);

		StringWriter w = new StringWriter();
		RDFWriter rdfWriter = rdfWriterFactory.getWriter(w);
		rdfWriter.getWriterConfig().set(JSONLDSettings.JSONLD_MODE, JSONLDMode.COMPACT);
		rdfWriter.getWriterConfig().set(JSONLDSettings.COMPACT_ARRAYS, true);
		rdfWriter.getWriterConfig().set(JSONLDSettings.USE_NATIVE_TYPES, true);

		rdfWriter.startRDF();
		rdfWriter.handleStatement(stmt);
		rdfWriter.endRDF();

		assertTrue(!w.toString().contains("@type"), "Does contain @type");
	}

	@Test
	public void testDirectedLanguageLiteralRoundTripPreservesBaseDirection() throws IOException {
		Statement expected = vf.createStatement(
				vf.createIRI(exNs, "subject"),
				vf.createIRI(exNs, "predicate"),
				vf.createLiteral("directional", "en", Literal.BaseDirection.LTR));
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		RDFWriter writer = rdfWriterFactory.getWriter(output);
		setupWriterConfig(writer.getWriterConfig());
		writer.startRDF();
		writer.handleStatement(expected);
		writer.endRDF();

		RDFParser parser = rdfParserFactory.getParser();
		setupParserConfig(parser.getParserConfig());
		Model parsed = new LinkedHashModel();
		parser.setRDFHandler(new StatementCollector(parsed));
		parser.parse(new ByteArrayInputStream(output.toByteArray()), "");

		assertTrue(parsed.contains(expected));
	}

	/**
	 * The legacy JSON-LD parser restores i18n datatype IRIs as directional literals. Inspect the serialized form
	 * directly to verify that RDF 1.1 output remains downgraded to the interoperable i18n datatype representation.
	 */
	@Override
	@Test
	public void testRDF12FullTo11Conversion() {
		Model model = createRDF12FullConversionModel();

		ByteArrayOutputStream output = new ByteArrayOutputStream();
		RDFWriter writer = rdfWriterFactory.getWriter(output);
		setupWriterConfig(writer.getWriterConfig());
		writer.getWriterConfig().set(BasicWriterSettings.RDF_OUTPUT_VERSION, VersionLabel.RDF_1_1);
		writer.startRDF();
		model.forEach(writer::handleStatement);
		writer.endRDF();

		assertRDF11Serialization(output.toString(StandardCharsets.UTF_8));
	}

	private Model createRDF12FullConversionModel() {
		Model model = new LinkedHashModel();
		BNode triple1Reifier = vf.createBNode();
		BNode triple2Reifier = vf.createBNode();
		BNode triple3Reifier = vf.createBNode();
		BNode triple5Reifier = vf.createBNode();
		BNode triple6Reifier = vf.createBNode();
		Literal rtlLiteral = vf.createLiteral("שלום", "he", Literal.BaseDirection.RTL);
		TripleTerm tripleTerm6 = vf.createTripleTerm(triple2Reifier, uri4, rtlLiteral);

		model.add(vf.createStatement(triple1Reifier, RDF.REIFIES, tripleTerm1, uri4));
		model.add(vf.createStatement(triple2Reifier, RDF.REIFIES, tripleTerm2, uri4));
		model.add(vf.createStatement(triple3Reifier, RDF.REIFIES, tripleTerm3, uri4));
		model.add(vf.createStatement(triple5Reifier, RDF.REIFIES, tripleTerm1, uri4));
		model.add(vf.createStatement(triple6Reifier, RDF.REIFIES, tripleTerm6, uri4));
		model.add(vf.createStatement(triple3Reifier, uri1, triple6Reifier, uri4));
		model.add(vf.createStatement(uri1, uri2, uri3, uri5));
		return model;
	}

	private void assertRDF11Serialization(String output) {
		assertTrue(output.contains("שלום"));
		assertTrue(output.contains("https://www.w3.org/ns/i18n#he_rtl"));
		assertFalse(output.contains("\"@language\""));
		assertFalse(output.contains("\"@direction\""));
		assertTrue(output.contains(RDF.PROPOSITION_FORM.stringValue()));
		assertTrue(output.contains(RDF.PROPOSITION_FORM_OBJECT.stringValue()));
		assertTrue(output.contains(RDF.REIFIES.stringValue()));
	}

